def top_words(text, n=3):
    counts = {}
    for w in tokenize(text):
        counts[w] = counts.get(w, 0) + 1
    # FIXME: this should be most common first
    ordered = sorted(counts.items(), key=lambda kv: kv[1])
    return ordered[:n]

